<?php $subtotal=array_sum(array_map(fn($i)=>$i['price']*$i['quantity'],$cart));$coupon=$_SESSION['coupon']??null;$discount=$coupon?min($subtotal,$coupon['type']==='percent'?$subtotal*(float)$coupon['value']/100:(float)$coupon['value']):0;$total=$subtotal-$discount;$error=$_SESSION['checkout_error']??null;unset($_SESSION['checkout_error']);$hasProduct=(bool)array_filter($cart,fn($i)=>($i['kind']??'')==='product');$hasPhysical=(bool)array_filter($cart,fn($i)=>($i['kind']??'')==='product'&&($i['product_type']??'physical')==='physical');$hasDigital=(bool)array_filter($cart,fn($i)=>($i['product_type']??'')==='digital');$hasTraining=(bool)array_filter($cart,fn($i)=>($i['kind']??'')==='formation');$viewer=$_SESSION['user']??[]; ?>
<section class="checkout-head"><p class="site-kicker">COMMANDE SÉCURISÉE</p><h1>Informations et paiement</h1><p><?= $hasDigital&&!$hasPhysical?'Votre téléchargement sera disponible immédiatement après le paiement.':'La livraison concerne uniquement les articles physiques.' ?></p></section><form class="checkout-layout" method="post" action="/commande"><div class="checkout-main"><?php if($error): ?><div class="auth-error"><?= htmlspecialchars($error) ?></div><?php endif ?><div class="checkout-box checkout-form"><h2>Vos coordonnées</h2><div class="field-grid"><label>Nom complet *<input name="name" value="<?= htmlspecialchars($viewer['name']??'') ?>" required></label><label>Email *<input type="email" name="email" value="<?= htmlspecialchars($viewer['email']??'') ?>" required></label><label>Téléphone *<input name="phone" value="<?= htmlspecialchars($viewer['phone']??'') ?>" required></label><label>Entreprise<input name="company"></label><?php if($hasPhysical): ?><label class="full">Adresse complète de livraison<textarea name="address" rows="3" placeholder="Commune, quartier, rue et repère"></textarea></label><?php endif ?></div></div><?php if($hasDigital): ?><div class="checkout-box digital-access"><span>↓</span><div><h2>Accès numérique immédiat</h2><p>Votre lien personnel apparaîtra après validation du paiement. Il restera actif 30 jours.</p></div></div><?php endif ?><?php if($hasPhysical): ?><div class="checkout-box choice-box"><h2>Réception</h2><label class="choice active"><input type="radio" name="delivery" value="pickup" checked><span>⌂</span><div><strong>Retrait gratuit</strong><small>Koumassi ou Yopougon</small></div></label><label class="choice"><input type="radio" name="delivery" value="delivery"><span>▣</span><div><strong>Livraison à domicile</strong><small>Suivi jusqu’à réception</small></div></label></div><?php else: ?><input type="hidden" name="delivery" value="pickup"><?php endif ?><div class="checkout-box choice-box"><h2>Mode de paiement</h2><label class="choice active"><input type="radio" name="payment" value="online" checked><span>▣</span><div><strong>Paiement Pro — Mobile Money / Carte</strong><small>Paiement sécurisé en ligne</small></div></label><?php if($hasPhysical&&!$hasTraining): ?><label class="choice"><input type="radio" name="payment" value="delivery"><span>◷</span><div><strong>Payer à la livraison</strong></div></label><?php endif ?></div></div><aside class="summary-card"><h2>Total de la commande</h2><?php foreach($cart as $item): ?><p><span><?= ($item['product_type']??'')==='digital'?'↓ ':'' ?><?= htmlspecialchars($item['name']) ?></span><b><?= number_format($item['price']*$item['quantity'],0,',',' ') ?></b></p><?php endforeach ?><?php if($discount): ?><p class="discount"><span>Remise <?= htmlspecialchars($coupon['code']) ?></span><b>− <?= number_format($discount,0,',',' ') ?></b></p><?php endif ?><hr><p class="total"><span>Total</span><strong><?= number_format($total,0,',',' ') ?> FCFA</strong></p><label style="display:block;margin:15px 0;font-size:13px"><input type="checkbox" name="accept_terms" value="1" required> J’accepte les <a href="/conditions-generales" target="_blank">conditions générales de vente et d’utilisation</a> et la <a href="/retours-remboursements" target="_blank">politique de retour et de remboursement</a>.</label><button class="site-btn gold wide">Confirmer et payer →</button></aside></form>
